{
  "source": "def audit(events, at):
    selected = {}
    for event in events:
        if event['seen'] > at:
            continue
        key = event['key']
        rev = event['rev']
        pair = (event['state'], event['stamp'])
        if key not in selected or rev > selected[key][0]:
            selected[key] = (rev, {pair})
        elif rev == selected[key][0]:
            selected[key][1].add(pair)
    result = {}
    for key, (_, pairs) in selected.items():
        if len(pairs) > 1:
            result[key] = 'conflict'
        else:
            state, stamp = next(iter(pairs))
            result[key] = 'stale' if at - stamp > 6 else state
    return result
