  "source": "def audit(events, at):
    observations = {}
    fixes = {}
    for event in events:
        if event['seen'] > at:
            continue
        key = event['key']
        rev = event['rev']
        pair = (event['state'], event['stamp'])
        if event['kind'] == 'obs':
            if key not in observations or rev > observations[key][0]:
                observations[key] = (rev, {pair})
            elif rev == observations[key][0]:
                observations[key][1].add(pair)
        elif event['kind'] == 'fix':
            target = (key, rev)
            n = event['n']
            if target not in fixes or n > fixes[target][0]:
                fixes[target] = (n, {pair})
            elif n == fixes[target][0]:
                fixes[target][1].add(pair)
    result = {}
    for key, (rev, pairs) in observations.items():
        if (key, rev) in fixes:
            pairs = fixes[(key, rev)][1]
        if len(pairs) > 1:
            result[key] = 'conflict'
        else:
            state, stamp = next(iter(pairs))
            result[key] = 'stale' if at - stamp > 6 else state
    return result
",
  "result": {
    "alder": "arrived",
    "balsa": "conflict",
    "cedar": "arrived"
  },
  "counterexample": {
    "events": [
      {"kind": "obs", "key": "x", "rev": 1, "state": "missed", "stamp": 19, "seen": 19},
      {"kind": "fix", "key": "x", "rev": 1, "n": 1, "state": "arrived", "stamp": 19, "seen": 18}
    ],
    "at": 20,
    "expected": {
      "x": "arrived"
    }
  }
}
